// Offline cache for the installed app. Network first so updates arrive; the cache answers when offline.
const CACHE='pogeun-island-22';
const CORE=['./accessories.js?v=18','./locomotion.js?v=18','./art/world/reference-island.jpg','./art/world/sky-terrain.json?v=11','./profile.js?v=10','./','./index.html','./island.css?v=19','./island.js?v=22','./wardrobe.js?v=22','./dom-render.js?v=5','./room.js?v=18','./art/world/cottage-room.webp','./momo.js?v=9','./cute.js?v=9','./livestock.js?v=9','./archipelago.js?v=9','./art/animals/cat-ginger.webp','./art/animals/hen.webp','./art/animals/duck.webp','./art/animals/sheep.webp','./art/animals/cow.webp','./art/animals/llama.webp','./movement.js?v=9','./weather.js?v=8','./shells.js?v=9','./art/humans/female-cozy.webp','./art/humans/male-cozy.webp','./art/world/sky-terrain.json','./art/world/sky-stage-1.webp','./art/world/sky-stage-2.webp','./art/world/sky-stage-3.webp','./art/world/sky-stage-4.webp','./art/world/sky-stage-5.webp','./art/world/sky-stage-6.webp','./core.js?v=9','./avatar.js?v=1','./rig.js?v=3','./human-sprites.js?v=22','./art/humans/catalog.json','./animal-visitors.js?v=9','./art/animals/catalog.json','./art/manifest.json','./manifest.webmanifest','./art/icon-192.png','./art/icon-512.png','../littlepark/garden-atlas.webp','../littlepark/momo-atlas.webp'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)).catch(()=>{}));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(n=>n.startsWith('pogeun-island-')&&n!==CACHE).map(n=>caches.delete(n)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));}return r;}).catch(()=>caches.match(e.request).then(r=>r||caches.match('./index.html'))));});
